import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.CqGS6Fr9.js";const k=JSON.parse('{"title":"Резервные копии и восстановление","description":"","frontmatter":{"pageId":"admins/backup-recovery","contentRevision":2},"headers":[],"relativePath":"ru/admins/backup-recovery.md","filePath":"ru/admins/backup-recovery.md"}'),i={name:"ru/admins/backup-recovery.md"};function l(o,a,p,n,c,d){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="резервные-копии-и-восстановление" tabindex="-1">Резервные копии и восстановление <a class="header-anchor" href="#резервные-копии-и-восстановление" aria-label="Permalink to &quot;Резервные копии и восстановление&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Используй согласованную копию БД и сейвов. Онлайн-копия: <code>rimlink-tools backup --data &lt;DataDir&gt; --out &lt;backup.tar.zst&gt;</code>; без --out файл появляется в backups. API POST /api/admin/backups создаёт копию, GET /backups перечисляет, GET /backups/{name} скачивает. Автоматически: Backup:IntervalHours=24, Keep=7 по умолчанию.</p><p>Перед восстановлением останови сервер, сохрани текущий каталог отдельно и проверь выбранную копию в изолированной среде. <code>rimlink-tools restore --data &lt;DataDir&gt; --from &lt;backup.tar.zst&gt;</code> заменяет БД и сейвы. После запуска проверь /health, версии сейвов, вход и доставку незавершённых операций. Не соединяй игроков с тестовой восстановленной копией.</p><p>Откат одного игрока через admin rollback — не полное восстановление сервера. Согласуй его с состоянием эскроу и восстановительными журналами клиента.</p><h2 id="restore-drill" tabindex="-1">Проверка backup в изоляции, шаг за шагом <a class="header-anchor" href="#restore-drill" aria-label="Permalink to &quot;Проверка backup в изоляции, шаг за шагом {#restore-drill}&quot;">​</a></h2><ol><li>Создай согласованный архив штатным backup и запиши время, версию сервера, размер и контрольную сумму. Скопируй архив вне единственного диска сервера.</li><li>Выбери <strong>новый тестовый каталог</strong>, не production DataDir. Убедись, что на него не смотрит ни один сервер. Сохрани конфигурацию/сертификат отдельно.</li><li>Выполни локально:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rimlink-tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./restore-drill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./copies/rimlink-selected.tar.zst</span></span></code></pre></div><ol start="4"><li>Запусти совместимую версию с DataDir=./restore-drill, отдельным портом и закрытым внешним доступом. Не направляй реальные клиенты на восстановленную копию.</li><li>Проверь health, статус мира, список версий сейва, открытие текущего и выбранного старого сейва тестового игрока; сверяй счётчики/почту с выбранным моментом. Простое наличие файлов недостаточно.</li><li>Зафиксируй результаты и только затем планируй production restore с остановкой, копией текущих данных и подтверждением.</li></ol><p>Команда restore <strong>заменяет базу и сейвы</strong> выбранного каталога. Этот пример — инструкция, не выполненная проверка твоего сервера.</p><h2 id="backup-scope" tabindex="-1">Что не исправляет whole-server restore? <a class="header-anchor" href="#backup-scope" aria-label="Permalink to &quot;Что не исправляет whole-server restore? {#backup-scope}&quot;">​</a></h2><p>Архив согласует базу и файлы сейвов под блокировкой. Не собирай их независимыми live-копиями и не удаляй save-storage.lock. Старые версии могут зависеть от delta-base; восстановление одного .rws.zst не равно восстановлению истории.</p><p>Откат всего сервера возвращает также экономику/социальные записи к моменту архива, но у клиентов остаются локальные журналы более поздних действий. До входа игроков нужен отдельный план согласования и сохранение этих доказательств. Не выдавай «очистить outbox всем» за универсальное решение.</p><p>Проверь отдельно внешние modpack-артефакты, исходные моды/лицензии, настройки службы и секреты. Backup:Keep распространяется и на архивы из панели; новый ручной backup может вытеснить самый старый.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не удаляй save-storage.lock: утилита держит его вместе с блокировкой хранилища на время снимка/упаковки. Не предполагается, что любая старая версия существует полным .rws.zst: она может быть delta. Проверяй восстановимость, а не только наличие архива.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./updating">Обновление сервера и клиентов</a></li><li><a href="./../developers/storage">Хранилище и эскроу</a></li><li><a href="./../players/saves-recovery">Сохранения и восстановление</a></li></ul>',19)])])}const u=e(i,[["render",l]]);export{k as __pageData,u as default};
